mapper.insert:
INSERT INTO SRS_CD (
    SRS_CD
  , STKPRC
  , BLBG_TCKR
  , ISIN_CD
  , EXCH_CD
  , CRC_CD
  , EXPR_DATE
  , GIJUN_STKPRC_YN
  , WEEK
) VALUES (
    #{srsCd}
  , #{stkprc}
  , #{blbgTckr}
  , #{isinCd}
  , #{exchCd}
  , #{crcCd}
  , REPLACE(#{exprDate}, '-', '')
  , NVL(#{gijunStkprcYn}, 'N')
  , #{week}
)

mapper.update:
UPDATE SRS_CD
   SET SRS_CD          = #{srsCd}
     , STKPRC          = #{stkprc}
     , BLBG_TCKR       = #{blbgTckr}
     , ISIN_CD         = #{isinCd}
     , EXCH_CD         = #{exchCd}
     , CRC_CD          = #{crcCd}
     , EXPR_DATE       = REPLACE(#{exprDate}, '-', '')
     , GIJUN_STKPRC_YN = NVL(#{gijunStkprcYn}, 'N')
     , WEEK            = #{week}
 WHERE SRS_CD = COALESCE(#{origSrsCd}, #{srsCd})

mapper.select:
SELECT COUNT(1)
  FROM SRS_CD
 WHERE SRS_CD = #{srsCd}
